guardrail.bad:
router.post('/users', async (req, res) => {
  const user = await userService.create(req.body); // unhandled rejection if throws
  res.json(user);
});

guardrail.good:
router.post('/users', async (req, res, next) => {
  try {
    const user = await userService.create(req.body);
    res.json(user);
  } catch (error) {
    next(error); // delegates to centralized error handler
  }
});

export const errorHandler = (
  error: Error, req: Request, res: Response, _next: NextFunction
) => {
  logger.error('Error:', { message: error.message, path: req.path, method: req.method });
  if (error instanceof AppError) {
    return res.status(error.statusCode).json({ status: 'error', message: error.message });
  }
  res.status(500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' ? 'Internal server error' : error.message,
  });
};

